{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2151-03-21 20:15:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee. I understand you came in today with a sore throat, eye irritation, and a rash. Can you tell me more about what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2151-03-21 20:16:30",
      "speaker": "Patient",
      "text": "Yes, I’ve had a sore throat for about three days, and my neck glands feel swollen. My eyes are red and itchy, especially around the lids. I think there’s a rash near my mouth, but the nurse didn’t see it."
    },
    {
      "turn_number": 3,
      "time": "2151-03-21 20:18:00",
      "speaker": "Doctor",
      "text": "I see. Any fever, cough, or runny nose?"
    },
    {
      "turn_number": 4,
      "time": "2151-03-21 20:18:45",
      "speaker": "Patient",
      "text": "No, I haven’t had a fever or cold symptoms. Just the sore throat, eyes, and this itchiness on my chest."
    },
    {
      "turn_number": 5,
      "time": "2151-03-21 20:20:00",
      "speaker": "Doctor",
      "text": "Okay. Given your history of stem cell transplant, we’re concerned this could be graft-versus-host disease, or GVHD. We’ll run some tests to be sure."
    },
    {
      "turn_number": 6,
      "time": "2151-03-21 20:21:30",
      "speaker": "Patient",
      "text": "GVHD again? I thought I was past that."
    },
    {
      "turn_number": 7,
      "time": "2151-03-21 20:22:45",
      "speaker": "Doctor",
      "text": "Chronic GVHD can flare up even months later. We’ll check your tacrolimus level—it helps prevent GVHD—and we’ll also look for infections like herpes or viruses."
    },
    {
      "turn_number": 8,
      "time": "2151-03-21 20:24:00",
      "speaker": "Patient",
      "text": "I’ve been taking my meds, but I did stop INH recently because of stomach pain."
    },
    {
      "turn_number": 9,
      "time": "2151-03-21 20:25:15",
      "speaker": "Doctor",
      "text": "That might explain the stomach issues, but not these new symptoms. We’ll keep monitoring. For now, we’ll admit you for observation and testing."
    },
    {
      "turn_number": 10,
      "time": "2151-03-22 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. Your CMV and respiratory virus tests came back negative. No flu, RSV, or adenovirus."
    },
    {
      "turn_number": 11,
      "time": "2151-03-22 09:02:00",
      "speaker": "Patient",
      "text": "So it’s not a cold or flu?"
    },
    {
      "turn_number": 12,
      "time": "2151-03-22 09:03:15",
      "speaker": "Doctor",
      "text": "No. That makes GVHD more likely. We’re going to do a skin biopsy today to check."
    },
    {
      "turn_number": 13,
      "time": "2151-03-22 09:04:30",
      "speaker": "Patient",
      "text": "Will it hurt?"
    },
    {
      "turn_number": 14,
      "time": "2151-03-22 09:05:45",
      "speaker": "Doctor",
      "text": "Just a small pinch with local numbing. It’s quick, and it’ll help us know how to treat you."
    },
    {
      "turn_number": 15,
      "time": "2151-03-22 14:00:00",
      "speaker": "Doctor",
      "text": "The biopsy is done. We sent the sample to pathology. Results should be back in a day or two."
    },
    {
      "turn_number": 16,
      "time": "2151-03-22 14:01:30",
      "speaker": "Patient",
      "text": "Thank you. My throat still hurts, and now I feel some sores inside my mouth."
    },
    {
      "turn_number": 17,
      "time": "2151-03-22 14:03:00",
      "speaker": "Doctor",
      "text": "We noticed white patches in your mouth. ENT looked and didn’t see ulcers, but we’re concerned it might be herpes. We’ll start you on valacyclovir just in case."
    },
    {
      "turn_number": 18,
      "time": "2151-03-22 14:04:30",
      "speaker": "Patient",
      "text": "But the throat swab was negative for HSV?"
    },
    {
      "turn_number": 19,
      "time": "2151-03-22 14:06:00",
      "speaker": "Doctor",
      "text": "Yes, but sometimes swabs miss it. Since you’ve had transplants, we don’t want to take chances. We’ll treat for 7 days and then go back to your usual acyclovir."
    },
    {
      "turn_number": 20,
      "time": "2151-03-23 08:30:00",
      "speaker": "Doctor",
      "text": "Your eye doctor saw you yesterday. They think your eye symptoms are due to GVHD. We’re starting lubricating drops and ointment."
    },
    {
      "turn_number": 21,
      "time": "2151-03-23 08:31:30",
      "speaker": "Patient",
      "text": "The drops help a little, but my eyes still burn."
    },
    {
      "turn_number": 22,
      "time": "2151-03-23 08:33:00",
      "speaker": "Doctor",
      "text": "We’ll increase the ointment to four times a day. It should soothe them more, especially at night."
    },
    {
      "turn_number": 23,
      "time": "2151-03-23 08:34:30",
      "speaker": "Patient",
      "text": "Okay, I’ll try that."
    },
    {
      "turn_number": 24,
      "time": "2151-03-23 15:00:00",
      "speaker": "Doctor",
      "text": "Your liver enzymes are a bit high. We’re not sure why yet—could be GVHD, meds, or something else. We’ll monitor them."
    },
    {
      "turn_number": 25,
      "time": "2151-03-23 15:01:30",
      "speaker": "Patient",
      "text": "Is that serious?"
    },
    {
      "turn_number": 26,
      "time": "2151-03-23 15:02:45",
      "speaker": "Doctor",
      "text": "Not necessarily. They’re only mildly elevated, and we’ve seen this before in transplant patients. We’ll repeat the labs and see if they improve."
    },
    {
      "turn_number": 27,
      "time": "2151-03-24 10:00:00",
      "speaker": "Doctor",
      "text": "The skin biopsy came back. It shows changes consistent with GVHD—interface dermatitis with apoptosis."
    },
    {
      "turn_number": 28,
      "time": "2151-03-24 10:01:30",
      "speaker": "Patient",
      "text": "So it’s definitely GVHD?"
    },
    {
      "turn_number": 29,
      "time": "2151-03-24 10:03:00",
      "speaker": "Doctor",
      "text": "Yes. The pathologist ruled out a viral rash. We’ll start topical steroids—clobetasol for your torso, triamcinolone for your neck, and tacrolimus ointment for your face."
    },
    {
      "turn_number": 30,
      "time": "2151-03-24 10:04:30",
      "speaker": "Patient",
      "text": "Will I need more steroids by mouth?"
    },
    {
      "turn_number": 31,
      "time": "2151-03-24 10:06:00",
      "speaker": "Doctor",
      "text": "We’re increasing your prednisone to 20mg in the morning and 15mg at night. It’ll help control the GVHD flare."
    },
    {
      "turn_number": 32,
      "time": "2151-03-24 10:07:30",
      "speaker": "Patient",
      "text": "I don’t like being on high steroids. I gained weight last time."
    },
    {
      "turn_number": 33,
      "time": "2151-03-24 10:09:00",
      "speaker": "Doctor",
      "text": "I understand. We’ll use the lowest effective dose and taper it as soon as you improve. This is temporary."
    },
    {
      "turn_number": 34,
      "time": "2151-03-24 14:00:00",
      "speaker": "Doctor",
      "text": "You developed a cough with yellow sputum. We did a chest CT—no pneumonia or fluid. It’s likely just irritation."
    },
    {
      "turn_number": 35,
      "time": "2151-03-24 14:01:30",
      "speaker": "Patient",
      "text": "It’s not serious then?"
    },
    {
      "turn_number": 36,
      "time": "2151-03-24 14:03:00",
      "speaker": "Doctor",
      "text": "No. The scan shows your lungs are clear. The old spot in your upper lobe has even improved. We won’t treat unless it worsens."
    },
    {
      "turn_number": 37,
      "time": "2151-03-25 09:00:00",
      "speaker": "Doctor",
      "text": "Your cough is better today. That’s good. The sputum culture just showed normal mouth bacteria, so no infection."
    },
    {
      "turn_number": 38,
      "time": "2151-03-25 09:01:30",
      "speaker": "Patient",
      "text": "And my abdominal pain? It’s still there, same as before."
    },
    {
      "turn_number": 39,
      "time": "2151-03-25 09:03:00",
      "speaker": "Doctor",
      "text": "We reviewed your history—it’s been chronic. We’ll get a CT of your abdomen to be safe."
    },
    {
      "turn_number": 40,
      "time": "2151-03-26 10:00:00",
      "speaker": "Doctor",
      "text": "The abdominal CT is back—completely normal. No inflammation, blockage, or fluid. Your pain is likely related to prior GVHD or nerve sensitivity."
    },
    {
      "turn_number": 41,
      "time": "2151-03-26 10:01:30",
      "speaker": "Patient",
      "text": "So nothing to do about it?"
    },
    {
      "turn_number": 42,
      "time": "2151-03-26 10:03:00",
      "speaker": "Doctor",
      "text": "We’ll keep managing it with pain meds. It hasn’t gotten worse, so that’s reassuring."
    },
    {
      "turn_number": 43,
      "time": "2151-03-27 08:00:00",
      "speaker": "Doctor",
      "text": "Your liver tests are trending down. That’s a good sign. We’re still ruling out hepatitis, but so far, everything looks okay."
    },
    {
      "turn_number": 44,
      "time": "2151-03-27 08:01:30",
      "speaker": "Patient",
      "text": "And my tacrolimus level?"
    },
    {
      "turn_number": 45,
      "time": "2151-03-27 08:03:00",
      "speaker": "Doctor",
      "text": "It was low. That might have contributed to the GVHD flare. We’re increasing your dose to 1mg twice daily."
    },
    {
      "turn_number": 46,
      "time": "2151-03-27 08:04:30",
      "speaker": "Patient",
      "text": "I’ll need blood tests to check it again?"
    },
    {
      "turn_number": 47,
      "time": "2151-03-27 08:06:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll monitor it regularly to keep it in the right range."
    },
    {
      "turn_number": 48,
      "time": "2151-03-28 09:00:00",
      "speaker": "Doctor",
      "text": "Your eye symptoms are still bothering you. We’re increasing the artificial tears to every two hours during the day."
    },
    {
      "turn_number": 49,
      "time": "2151-03-28 09:01:30",
      "speaker": "Patient",
      "text": "That’s a lot of drops."
    },
    {
      "turn_number": 50,
      "time": "2151-03-28 09:03:00",
      "speaker": "Doctor",
      "text": "I know. But dry eyes from GVHD can get worse if not treated well. We want to protect your vision."
    },
    {
      "turn_number": 51,
      "time": "2151-03-28 09:04:30",
      "speaker": "Patient",
      "text": "Okay, I’ll do it."
    },
    {
      "turn_number": 52,
      "time": "2151-03-29 10:00:00",
      "speaker": "Doctor",
      "text": "Big improvements today. Your rash is less red, your throat feels better, and your eyes are less irritated."
    },
    {
      "turn_number": 53,
      "time": "2151-03-29 10:01:30",
      "speaker": "Patient",
      "text": "I feel much better. Can I go home?"
    },
    {
      "turn_number": 54,
      "time": "2151-03-29 10:03:00",
      "speaker": "Doctor",
      "text": "Yes, we’re planning to discharge you tomorrow. We’ll give you prescriptions for the creams, eye drops, and valacyclovir for seven days."
    },
    {
      "turn_number": 55,
      "time": "2151-03-29 10:04:30",
      "speaker": "Patient",
      "text": "And the prednisone?"
    },
    {
      "turn_number": 56,
      "time": "2151-03-29 10:06:00",
      "speaker": "Doctor",
      "text": "You’ll stay on 20mg in the morning and 15mg at night for now. Your transplant team will help taper it slowly."
    },
    {
      "turn_number": 57,
      "time": "2151-03-29 10:07:30",
      "speaker": "Patient",
      "text": "And the tacrolimus?"
    },
    {
      "turn_number": 58,
      "time": "2151-03-29 10:09:00",
      "speaker": "Doctor",
      "text": "Now 1mg twice daily. Keep taking it exactly as prescribed to prevent more flares."
    },
    {
      "turn_number": 59,
      "time": "2151-03-29 10:10:30",
      "speaker": "Patient",
      "text": "What about the nystatin?"
    },
    {
      "turn_number": 60,
      "time": "2151-03-29 10:12:00",
      "speaker": "Doctor",
      "text": "Yes, four times a day. It’s to prevent mouth fungus, especially with the steroids."
    },
    {
      "turn_number": 61,
      "time": "2151-03-30 08:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re discharging you today. Keep using all the creams and eye treatments as directed."
    },
    {
      "turn_number": 62,
      "time": "2151-03-30 08:01:30",
      "speaker": "Patient",
      "text": "Thank you. I’ll follow up with my transplant doctor?"
    },
    {
      "turn_number": 63,
      "time": "2151-03-30 08:03:00",
      "speaker": "Doctor",
      "text": "Yes, and call us if you develop fever, trouble eating, or any new symptoms. You’ve done great."
    },
    {
      "turn_number": 64,
      "time": "2151-03-30 08:04:30",
      "speaker": "Patient",
      "text": "I will. Thanks for taking care of me."
    },
    {
      "turn_number": 65,
      "time": "2151-03-30 08:06:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Get some rest and take it easy at home."
    },
    {
      "turn_number": 66,
      "time": "2151-03-30 08:07:30",
      "speaker": "Patient",
      "text": "I plan to."
    },
    {
      "turn_number": 67,
      "time": "2151-03-30 08:09:00",
      "speaker": "Doctor",
      "text": "One more thing—your liver enzymes are still a bit high but improving. Your transplant team will monitor them."
    },
    {
      "turn_number": 68,
      "time": "2151-03-30 08:10:30",
      "speaker": "Patient",
      "text": "Should I worry?"
    },
    {
      "turn_number": 69,
      "time": "2151-03-30 08:12:00",
      "speaker": "Doctor",
      "text": "Not right now. It’s likely related to GVHD or meds. As long as they keep trending down, we’re on the right track."
    },
    {
      "turn_number": 70,
      "time": "2151-03-30 08:13:30",
      "speaker": "Patient",
      "text": "Okay, that’s a relief."
    },
    {
      "turn_number": 71,
      "time": "2151-03-30 08:15:00",
      "speaker": "Doctor",
      "text": "We’ll see you in clinic soon. Take care."
    },
    {
      "turn_number": 72,
      "time": "2151-03-30 08:16:30",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 73,
      "time": "2151-03-30 08:18:00",
      "speaker": "Doctor",
      "text": "The nurse will go over your discharge instructions and medications before you leave."
    },
    {
      "turn_number": 74,
      "time": "2151-03-30 08:19:30",
      "speaker": "Patient",
      "text": "Got it."
    },
    {
      "turn_number": 75,
      "time": "2151-03-30 08:21:00",
      "speaker": "Doctor",
      "text": "And remember—artificial tears every two hours while awake, and lacrilube four times a day, especially at night."
    },
    {
      "turn_number": 76,
      "time": "2151-03-30 08:22:30",
      "speaker": "Patient",
      "text": "I’ll set reminders."
    },
    {
      "turn_number": 77,
      "time": "2151-03-30 08:24:00",
      "speaker": "Doctor",
      "text": "Good idea. That’ll help keep your eyes comfortable."
    },
    {
      "turn_number": 78,
      "time": "2151-03-30 08:25:30",
      "speaker": "Patient",
      "text": "I’m glad this flare is under control."
    },
    {
      "turn_number": 79,
      "time": "2151-03-30 08:27:00",
      "speaker": "Doctor",
      "text": "So are we. You responded well to treatment. Keep up the good work."
    },
    {
      "turn_number": 80,
      "time": "2151-03-30 08:28:30",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 81,
      "time": "2151-03-30 08:30:00",
      "speaker": "Doctor",
      "text": "We’ll get your discharge papers ready. Safe travels home."
    },
    {
      "turn_number": 82,
      "time": "2151-03-30 08:31:30",
      "speaker": "Patient",
      "text": "Thank you again."
    },
    {
      "turn_number": 83,
      "time": "2151-03-30 08:33:00",
      "speaker": "Doctor",
      "text": "Take care of yourself."
    },
    {
      "turn_number": 84,
      "time": "2151-03-30 08:34:30",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 85,
      "time": "2151-03-30 08:36:00",
      "speaker": "Doctor",
      "text": "See you in clinic."
    }
  ],
  "summary": {
    "admission_start": "2151-03-21 19:54:00",
    "admission_end": "2151-03-30 18:30:00",
    "summary_paragraph": "The patient was admitted for evaluation of a rash, eye irritation, and sore throat following an allogeneic stem cell transplant for CML in myeloblastic crisis. Initial workup ruled out viral infections, and a skin biopsy confirmed chronic graft-versus-host disease (GVHD) affecting the skin and eyes. Oral lesions suggestive of herpes simplex virus were treated with a 7-day course of valacyclovir. Symptoms improved with increased prednisone, higher-dose tacrolimus, and topical therapies for the skin and eyes. Transaminitis was noted but trended downward, likely related to GVHD or medication effects. Abdominal pain was chronic and unchanged, with a normal CT abdomen. The patient stabilized, symptoms resolved, and she was discharged home with updated immunosuppressive and supportive therapies.",
    "problems": [
      "Complications of transplanted bone marrow",
      "Herpes simplex with other specified complications",
      "Chronic graft-versus-host disease",
      "Conjunctivitis, unspecified",
      "Abdominal pain, unspecified site",
      "Nonspecific elevation of levels of transaminase or lactic acid dehydrogenase [LDH]",
      "Cough"
    ]
  }
}
